-- More fashion and human scenes: outfits and accessories per mood.
-- The phrases stay pure pet logic.
update public.personalities set image_prompt = 'Dress the pet in a pearl necklace, a chic faux-fur stole and oversized sunglasses. Place it on a red carpet at a glamorous premiere with velvet ropes and camera flashes in the blurred background.' where id in ('pt-diva', 'en-diva');
update public.personalities set image_prompt = 'Tie an elegant white napkin around the pet''s neck and add a small bow tie. Seat it at a candlelit restaurant table with a silver cloche, a full plate of food, cutlery and a bread basket.' where id in ('pt-esfomeado', 'en-esfomeado');
update public.personalities set image_prompt = 'Dress the pet in a chic winter hat, a wool coat and a knitted scarf. Place it on an elegant snowy city street at dusk with warm shop lights behind; bright enough to see the face clearly, wistful mood.' where id in ('pt-dramatico', 'en-dramatico');
update public.personalities set image_prompt = 'Dress the pet in a black cape with a high collar and a monocle. Seat it in a big leather armchair in a wood-panelled study with a fireplace, a globe and a glass standing on the edge of a side table.' where id in ('pt-vilao', 'en-vilao');
update public.personalities set image_prompt = 'Dress the pet in silk pajamas with a sleep mask pushed up on its forehead. Place it in a luxurious hotel bed with fluffy white pillows and a breakfast tray, soft morning light.' where id in ('pt-preguicoso', 'en-preguicoso');
update public.personalities set image_prompt = 'Dress the pet in a detective trench coat, a fedora hat and dark sunglasses. Seat it at a café table, peeking over a blank newspaper with a suspicious side-eye, a smartphone on the table.' where id in ('pt-ciumento', 'en-ciumento');
update public.personalities set image_prompt = 'Give the pet a party hat, a loose bow tie and funny sunglasses. Place it in a living room the morning after a wild party: confetti, streamers, tipped-over cups and a knocked-over plant.' where id in ('pt-caotico', 'en-caotico');
update public.personalities set image_prompt = 'Dress the pet in a black beret, a silk scarf and small round glasses. Seat it at a fine-dining restaurant table with a white tablecloth, a tiny gourmet dish and a notebook. No readable text.' where id in ('pt-critico', 'en-critico');
